//! What setting or clearing an axis Unit does to that axis's Label, Symbol
//! and Format, checked against the C library.
//!
//! `new_unit_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/new_unit_probe.c`. With ActiveUnit set, C rewrites
//! a set Label and Symbol for the new Unit and clears a set Format when the
//! Unit changes (frame.c `SetUnit`, `ClearUnit`, `NewUnit`); trailing spaces
//! are dropped from the Unit.

#[path = "new_unit_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{
    BasicFrameBuilder, DynFrame, Frame, SpecFrame, SpecSystem, TimeFrame, TimeSystem,
};

fn frame(active: bool) -> DynFrame {
    let mut f = BasicFrameBuilder::new(1).build().unwrap();
    f.set_label(1, "Dist").unwrap();
    f.set_symbol(1, "d").unwrap();
    f.set_format_str(1, "%.2f").unwrap();
    f.set_unit(1, "m").unwrap();
    f.set_active_unit(active);
    Box::new(f)
}

fn run(name: &str) -> DynFrame {
    match name {
        "active_log" | "active_km" | "active_same" | "inactive_log" | "active_trailing_spaces" => {
            let (active, unit) = match name {
                "active_log" => (true, "log(m)"),
                "active_km" => (true, "km"),
                "active_same" => (true, "m"),
                "inactive_log" => (false, "log(m)"),
                _ => (true, "km   "),
            };
            let mut f = frame(active);
            f.set_unit(1, unit).unwrap();
            f
        }
        "active_clear" => {
            let mut f = frame(true);
            f.clear_unit(1).unwrap();
            f
        }
        "spec_log" | "spec_mhz" => {
            let mut f = SpecFrame::new(SpecSystem::Freq);
            f.set_label(1, "Nu").unwrap();
            if name == "spec_log" {
                f.set_symbol(1, "n").unwrap();
            }
            f.set_format_str(1, "%.3f").unwrap();
            f.set_unit(1, if name == "spec_log" { "log(Hz)" } else { "MHz" })
                .unwrap();
            Box::new(f)
        }
        "time_s" => {
            let mut f = TimeFrame::new(TimeSystem::Mjd);
            f.set_label(1, "When").unwrap();
            f.set_format_str(1, "%.3f").unwrap();
            f.set_unit(1, "s").unwrap();
            Box::new(f)
        }
        other => panic!("no Rust set-up for case {other}"),
    }
}

#[test]
fn unit_changes_match_the_c_library() {
    let mut failures = Vec::new();
    for &(name, label, symbol, test_format, unit) in cases::CASES {
        let f = run(name);
        let got = (
            f.label(1).unwrap(),
            f.symbol(1).unwrap(),
            f.test_format_str(1).unwrap(),
            f.unit(1).unwrap(),
        );
        let want = (
            label.to_string(),
            symbol.to_string(),
            test_format,
            unit.to_string(),
        );
        if got != want {
            failures.push(format!("{name}: got {got:?}, C gives {want:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
